#include "resident/domains/military/military_model.hpp"
// 原围城request和quote逐字段适配；不在codec中裁决军团位置、材料或战略可行性。
#include "siege_command_codec.hpp"
#include "siege_codec.hpp"
#include "resident/domains/conditions/domain_codec_util.hpp"
namespace hanmo::resident {
namespace {using V=BoundaryValue;using D=V::Dict;using A=V::Array;V ids(const std::vector<StableId>& rows){A out;for(auto& id:rows)out.push_back(V{id});return V{out};}}
Outcome<MilitaryCommand> decode_siege_command(const StableId& kind,const BoundaryValue& p){try{boundary::object(p,"params");auto str=[&](const char* key){auto x=p.find(key);return x&&x->as<StableId>()?*x->as<StableId>():StableId{};};auto order=domain_codec::order(p);if(kind=="siege_start")return {true,SiegeStart{str("campaign_id"),order},{}};if(kind=="siege_join")return {true,SiegeJoin{str("siege_id"),str("campaign_id"),order},{}};if(kind=="siege_close")return {true,SiegeClose{str("siege_id"),order},{}};if(kind=="siege_plan"){SiegePlan r;r.siege_id=str("siege_id");r.field_order=order;auto x=p.find("orders");if(!x||!x->as<D>())r.orders_valid=false;else for(auto& row:*x->as<D>()){SiegeOrder o;siege_codec::decode(row.second,o,"orders/"+row.first);r.orders.emplace_back(row.first,o);}return {true,r,{}};}if(kind=="siege_strategy"){SiegeStrategy r;r.siege_id=str("siege_id");r.field_order=order;auto x=p.find("command");if(!x||!x->as<D>())r.command_valid=false;else{r.command.field_order=domain_codec::order(*x);auto field=[&](const char* key){auto v=x->find(key);return v&&v->as<StableId>()?*v->as<StableId>():StableId{};};r.command.kind=field("kind");r.command.army_id=field("army_id");r.command.terms=field("terms");for(auto& row:*x->as<D>())if(row.first!="kind"&&row.first!=(r.command.kind=="withdraw"?"army_id":"terms"))r.command.unexpected_fields.push_back(row.first);}return {true,r,{}};}return {false,{},common_failure("UnknownSiegeCommand").error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<BoundaryValue> encode_siege_quote(const MilitaryQuote& q,const MilitaryCommand& command){D d{{"ok",V{true}}};if(std::holds_alternative<SiegeStart>(command)){if(!q.siege_request)return {false,{},common_failure("InvalidSiegeRequest").error};auto& r=*q.siege_request;d.emplace_back("request",V{D{{"id",V{r.id}},{"campaign_id",V{r.campaign_id}},{"stronghold_id",V{r.stronghold_id}},{"attacker_army_ids",ids(r.attacker_army_ids)},{"defender_army_ids",ids(r.defender_army_ids)}}});d.emplace_back("duration",V{Integer(0)});}else if(std::holds_alternative<SiegeClose>(command))d.emplace_back("duration",V{Integer(0)});else if(q.siege_resolution){d.emplace_back("siege",siege_codec::encode(q.siege_resolution->siege));if(std::holds_alternative<SiegeStrategy>(command)){A events;for(auto& e:q.siege_resolution->events)events.push_back(siege_codec::encode(e));d.emplace_back("events",V{events});}}return {true,V{std::move(d)},{}};}
}
